def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    markers = {v for v in counts if v != background}
    out = [row[:] for row in grid]
    for marker in markers:
        for r in range(h):
            xs = [c for c, v in enumerate(grid[r]) if v == marker]
            for a, b in zip(xs, xs[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 3
        for c in range(w):
            ys = [r for r in range(h) if grid[r][c] == marker]
            for a, b in zip(ys, ys[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 3
    return out

